{
  "justification": "The electorate is centrist on left–right and redistribution but leans authoritarian on social issues (authority–liberty mean 6.2), with immigration highly salient. Cost-of-living and the economy dominate salience, with health and environment secondary, suggesting stronger weight for care, authority, and proportionality, moderate equality, and lower sanctity.",
  "foundations": [
    {
      "foundation": "authority",
      "basis": "Authority–liberty scale mean 6.2 (higher more authoritarian); salience of immigration, crime, defence.",
      "weight": 0.22
    },
    {
      "foundation": "care",
      "basis": "Salience: living costs 19.7%, health 7.0%, poverty 1.3%, inequality 1.1%.",
      "weight": 0.20
    },
    {
      "foundation": "proportionality",
      "basis": "Salience: economy-general 13.7%, living costs 19.7%, taxation/debt/inflation items.",
      "weight": 0.20
    },
    {
      "foundation": "equality",
      "basis": "Redistribution position mean 4.68 (centrist); salience of inequality/poverty/welfare/taxation.",
      "weight": 0.16
    },
    {
      "foundation": "loyalty",
      "basis": "High salience of immigration 17.0% plus defence/war and national identity items.",
      "weight": 0.13
    },
    {
      "foundation": "sanctity",
      "basis": "Environment 6.1% plus smaller morals (0.3%) and gender/sexuality/family (0.1%) salience.",
      "weight": 0.09
    }
  ]
}
